insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('d5299df0-a545-55f0-9f8a-8e70cbdee46e', '0be9de42-1932-5e69-812b-f328df1147b3', 'Red kids tricycle, ages 2-4', 'Classic red trike with chrome handlebars and streamers taken off. Wheels roll straight, seat is adjustable. Some scuffs on the step plate. My youngest moved to a balance bike. Helmet not included.', 25, 'kids', 'good', 'active', '[{"fileId":"6aceef5eead997d09a5feb1a","path":"/stoop/seed/red-tricycle-1.jpg","width":960,"height":640}]'::jsonb, 40.675, -73.94, 'Crown Heights, Brooklyn', now() - interval '3324 minutes', now() - interval '3324 minutes', true);
